const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || headers.Authorization;
if (!authHeader || typeof authHeader !== 'string') { throw new Error('Unauthorized'); }
const parts = authHeader.split(' ');
if (parts.length < 2 || !parts[1]) { throw new Error('Unauthorized'); }
const tokenParts = parts[1].split('.');
if (tokenParts.length < 2) { throw new Error('Unauthorized'); }
const base64 = tokenParts[1].replace(/-/g, '+').replace(/_/g, '/');
const payload = JSON.parse(Buffer.from(base64, 'base64').toString('utf8'));
const body = $input.first().json.body || {};

const allowedTypes = ['pdf', 'docx', 'pptx', 'txt', 'image'];
const title = (body.title || '').toString().trim();
const fileName = (body.file_name || '').toString().trim();
const fileType = (body.file_type || '').toString().trim().toLowerCase();

let validationError = null;
if (!title) validationError = 'اسم الكتاب مطلوب';
else if (title.length > 200) validationError = 'اسم الكتاب طويل جدًا';
else if (!fileName) validationError = 'اسم الملف مطلوب';
else if (!allowedTypes.includes(fileType)) validationError = 'نوع الملف غير مدعوم (PDF أو Word أو PowerPoint أو نص أو صورة فقط)';

// اسم فريد وآمن للملف داخل مجلد المعلم في التخزين (يمنع تعارض الأسماء ويشيل أي رموز قد تكسر الرابط)
const safeName = fileName.replace(/[^a-zA-Z0-9\u0600-\u06FF._-]/g, '_').slice(-80);
const uniqueToken = Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
const storagePath = `${payload.sub}/${uniqueToken}-${safeName}`;

return {
  teacherId: payload.sub,
  title,
  fileName,
  fileType,
  storagePath,
  isValid: validationError === null,
  validationError
};

